"""Summarize workflow tables without changing the node."""
import argparse
from datetime import datetime, timedelta, timezone
from decimal import Decimal
import json
from pathlib import Path
import re

EVERY = re.compile(r"[1-9][0-9]*[rsmhd]\Z")
CODE = re.compile(r"[+-]?[0-9]+\Z")
SECONDS = {"s": 1, "m": 60, "h": 3600, "d": 86400}
REQUIRED = {
    "routines": ("name", "every", "last_time", "last_code"),
    "schedule": ("name", "at", "claimed"),
}


def reject_constant(value):
    raise ValueError("nonfinite JSON constant: " + value)


def read_table(node, table):
    try:
        with (node / "wf" / (table + ".json")).open(encoding="utf-8") as stream:
            data = json.load(stream, parse_constant=reject_constant, parse_float=Decimal)
        if (not isinstance(data, dict) or data.get("contract") != "wf-table/1"
                or not isinstance(data.get("columns"), list)
                or not all(isinstance(column, str) for column in data["columns"])
                or not isinstance(data.get("rows"), list)):
            raise ValueError("invalid table")
        return data["rows"], []
    except FileNotFoundError:
        return [], []
    except (OSError, UnicodeError, ValueError):
        return [], [{"table": table, "row": None, "why": "bad_table"}]


def timestamp(value, now):
    parsed = datetime.fromisoformat(value)
    return parsed if parsed.tzinfo is not None else parsed.replace(tzinfo=now.tzinfo)


def routine(row, now):
    every = row["every"]
    if not EVERY.fullmatch(every):
        raise ValueError("invalid interval")
    last_time = row["last_time"]
    stamp = timestamp(last_time, now) if last_time else None
    raw_code = row["last_code"]
    if raw_code == "":
        code = None
    elif raw_code == "running":
        code = raw_code
    elif CODE.fullmatch(raw_code):
        code = int(raw_code)
    else:
        raise ValueError("invalid code")
    due = None
    if stamp is not None and every[-1] != "r":
        due = stamp + timedelta(seconds=int(every[:-1]) * SECONDS[every[-1]])
    if code == "running":
        state = "running"
    elif stamp is None:
        state = "never"
    elif isinstance(code, int) and code != 0:
        state = "failed"
    elif due is not None and now >= due:
        state = "overdue"
    else:
        state = "ok"
    next_time = due.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ") if due else None
    return {"name": row["name"], "every": every, "last_time": last_time or None,
            "last_code": code, "state": state, "next": next_time}


def scheduled(row, now):
    at = timestamp(row["at"], now)
    state = "interrupted" if row["claimed"] else "due" if at <= now else "pending"
    return {"name": row["name"], "at": row["at"], "state": state}


def summarize(node, now):
    output = {"v": 1, "routines": [], "schedule": [], "counts": {
        "routines": {key: 0 for key in ("running", "never", "failed", "overdue", "ok")},
        "schedule": {key: 0 for key in ("interrupted", "due", "pending")}}, "bad": []}
    for table, convert in (("routines", routine), ("schedule", scheduled)):
        rows, errors = read_table(node, table)
        output["bad"].extend(errors)
        seen = set()
        for index, row in enumerate(rows):
            name = row.get("name") if isinstance(row, dict) else None
            if isinstance(name, str) and name:
                if name in seen:
                    output["bad"].append({"table": table, "row": index, "why": "dup_name"})
                    continue
                seen.add(name)
            if (not isinstance(row, dict) or not all(isinstance(v, str) for v in row.values())
                    or any(key not in row for key in REQUIRED[table]) or not name):
                output["bad"].append({"table": table, "row": index, "why": "bad_row"})
                continue
            try:
                item = convert(row, now)
            except (ValueError, OverflowError):
                output["bad"].append({"table": table, "row": index, "why": "bad_row"})
                continue
            output[table].append(item)
            output["counts"][table][item["state"]] += 1
        output[table].sort(key=lambda item: item["name"])
    output["bad"].sort(key=lambda item: (item["table"], -1 if item["row"] is None else item["row"], item["why"]))
    return output


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only workflow summary")
    parser.add_argument("node", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("invalid --now")
    if now.tzinfo is None:
        parser.error("--now requires a timezone")
    if not args.node.is_dir():
        parser.error("node is not a directory")
    print(json.dumps(summarize(args.node, now), ensure_ascii=True, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
